package com.project7.localmanager;
import java.io.*;import java.lang.reflect.*;import java.util.*;
/** Pure candidate mutation; same original Store runner owns commit. */
public final class BaiyeShopPolicy {
 private static final Method REFRESH=BaiyeTransactions.Access.method(LocalCommerceEngine.class,"refreshStoreLimits",byte[].class,true,byte[].class,long.class),SPEND=BaiyeTransactions.Access.method(LocalCommerceEngine.class,"spend",byte[].class,true,byte[].class,String.class,int.class),COUNTS=BaiyeTransactions.Access.method(LocalCommerceEngine.class,"pairCounts",Map.class,true,byte[].class),PAIRS=BaiyeTransactions.Access.method(LocalCommerceEngine.class,"pairs",List.class,true,Map.class),STORY=BaiyeTransactions.Access.method(LocalCommerceEngine.class,"storyCounts",Map.class,true,byte[].class),STORY_PAIRS=BaiyeTransactions.Access.method(LocalCommerceEngine.class,"storyPairs",List.class,true,Map.class);
 private BaiyeShopPolicy(){}
 static byte[]doc(byte[]p,String key){return BaiyeFragments.doc(p,key);}
 @SuppressWarnings("unchecked") static Map<Integer,Integer>counts(byte[]d)throws IOException{return(Map<Integer,Integer>)BaiyeTransactions.call(COUNTS,null,d);}
 static int value(byte[]p,String key){Number n=BsonLite.numericValue(p,key);if(n==null&&!BsonLite.keys(p).contains(key))return 0;if(!(n instanceof Integer)||n.intValue()<0)throw new IllegalArgumentException("Profile integer");return n.intValue();}
 static boolean listOwns(byte[]items,int id){if(items==null)return false;BaiyeTransactions.document(items);List<byte[]>rows=LocalResourceEngine.array(items);if(rows.size()!=BsonLite.keys(items).size())throw new IllegalArgumentException("Owned inventory");for(byte[]row:rows)if(Integer.valueOf(id).equals(BsonLite.intValue(row,"i"))&&BsonLite.documentValue(row,"tr")!=null)return true;return false;}
 static boolean owns(byte[]profile,int id){if(listOwns(BsonLite.arrayValue(doc(profile,"inv"),"items"),id))return true;byte[]heroes=BsonLite.arrayValue(doc(profile,"heromgr"),"hrs");if(heroes==null)return false;for(byte[]pair:LocalResourceEngine.array(heroes)){byte[]hero=BsonLite.documentValue(pair,"1");if(hero==null)throw new IllegalArgumentException("Hero pair");if(listOwns(BsonLite.arrayValue(doc(hero,"ti"),"items"),id))return true;}return false;}
 public static LocalResourceEngine.Result apply(byte[]before,LocalResourceCatalog resources,byte[]params,long nowMillis)throws IOException{
  BaiyeTransactions.document(params);int id=BaiyeTransactions.positive(BsonLite.numericValue(params,"store_id")),number=BaiyeTransactions.positive(BsonLite.numericValue(params,"num"));BaiyeShopCatalog.Product p=BaiyeShopCatalog.get(id);if(p==null||number>1000000||value(params,"coin_type")!=0||nowMillis<=0)throw new IllegalArgumentException("Purchase scope");
  if(BsonLite.keys(params).contains("_cbid_"))BaiyeTransactions.positive(BsonLite.numericValue(params,"_cbid_"));
  Set<String>allowed=new HashSet<>(Arrays.asList("store_id","num","coin_type","ext","source","_cbid_"));if(!allowed.containsAll(BsonLite.keys(params)))throw new IllegalArgumentException("Purchase keys");if(BsonLite.keys(params).contains("source")&&BsonLite.stringValue(params,"source")==null)throw new IllegalArgumentException("Purchase source");byte[]ext=doc(params,"ext");if(!new HashSet<>(Arrays.asList("silence","flow_message")).containsAll(BsonLite.keys(ext)))throw new IllegalArgumentException("Purchase ext");for(String key:BsonLite.keys(ext))if(BsonLite.boolValue(ext,key)==null)throw new IllegalArgumentException("Purchase flag");boolean silence=Boolean.TRUE.equals(BsonLite.boolValue(ext,"silence"));
  byte[]profile=(byte[])BaiyeTransactions.call(REFRESH,null,before,nowMillis);byte[]ldd=doc(profile,"ldd");int week=value(doc(profile,"weeknum"),"w");if(week<p.minWeek)throw new IllegalArgumentException("Story week");String key=Integer.toString(id);List<Object>projections=new ArrayList<>();String[]names={"din","win","ton","mon"};
  for(int i=0;i<names.length;i++){Map<Integer,Integer>m=counts(BsonLite.documentValue(ldd,names[i]));Integer old=m.get(id);if(old!=null&&old<0)throw new IllegalArgumentException("Purchase count");int next=Math.addExact(old==null?0:old,number);int limit=i==1?p.weekly:i==2?p.total:0;if(limit>0&&next>limit)throw new IllegalArgumentException("Purchase limit");m.put(id,next);Object pairs=BaiyeTransactions.call(PAIRS,null,m);projections.add(pairs);ldd=BsonLite.withProfileArray(ldd,names[i],(List<?>)pairs);}
  profile=BsonLite.withProfileDocument(profile,"ldd",ldd);LocalResourceEngine.Result r=new LocalResourceEngine.Result(profile);int cost=Math.multiplyExact(p.cost,number);
  if(p.payment.equals("item")){if(BaiyeTransactions.count(r.profile,p.costItem)<cost)throw new IllegalArgumentException("Item cost");LocalGiftEngine.consume(r,p.costItem,cost);}else r.profile=(byte[])BaiyeTransactions.call(SPEND,null,r.profile,p.payment,cost);
  if(p.kind.equals("item")){int quantity=Math.multiplyExact(p.quantity,number);if(BaiyeTransactions.count(r.profile,p.item)>Integer.MAX_VALUE-quantity)throw new IllegalArgumentException("Item overflow");LocalResourceEngine.grant(r,resources,"item",p.item,quantity,p.quality,p.tr);}
  else for(int i=0;i<number;i++){
   if(owns(r.profile,p.item)){if(BaiyeTransactions.count(r.profile,p.reget)>Integer.MAX_VALUE-p.regetCount)throw new IllegalArgumentException("Reget overflow");LocalResourceEngine.grant(r,resources,"item",p.reget,p.regetCount,1);}
   else LocalResourceEngine.grant(r,resources,"treasure",p.item,p.quantity,p.quality,p.tr);
  }
  LocalResourceEngine.syncCurrencies(r);r.add("replyBuyCardMallItem",BsonLite.document("r",true,"i",BsonLite.EMPTY_DOCUMENT));Object stories=BaiyeTransactions.call(STORY_PAIRS,null,BaiyeTransactions.call(STORY,null,ldd));r.add("buyCardMallItemDone",BsonLite.document("d",projections.get(0),"w",projections.get(1),"t",projections.get(2),"m",projections.get(3),"z",stories,"itemid",p.item,"num",number,"result",r.reward(),"sd",id,"silence",silence));return r;
 }
}
